(()=>{'use strict';const c=window.matclubCppCourse,host=document.getElementById('cppCourse');if(!c||!host)return;const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));let saved={};try{saved=JSON.parse(localStorage.getItem('matclub-cpp-v1'))||{}}catch{}const ids=new Set(c.lessons.map(l=>l.id));let id=ids.has(saved.id)?saved.id:c.lessons[0].id;const drafts={},done=new Set(Array.isArray(saved.done)?saved.done.filter(x=>ids.has(x)):[]);for(const l of c.lessons)if(typeof saved.drafts?.[l.id]==='string')drafts[l.id]=saved.drafts[l.id].slice(0,100000);const $=s=>host.querySelector(s);function persist(){try{localStorage.setItem('matclub-cpp-v1',JSON.stringify({id,drafts,done:[...done]}));$('#cppSaved').textContent='Сохранено в этом браузере'}catch{$('#cppSaved').textContent='Сохранение недоступно. Скачай код.'}}function render(){const l=c.lessons.find(l=>l.id===id),index=c.lessons.indexOf(l);host.innerHTML=`<div class="py-course-head"><div><span class="alpha-badge">КУРС ОТКРЫТ · C++17</span><h3>От первой программы до своих проектов</h3><p>20 уроков, 2 проекта, объяснения, практика и вопросы на понимание.</p></div><div class="py-progress-box"><span>Пройдено ${done.size} из 22 тем</span><progress max="22" value="${done.size}" aria-label="Прогресс курса"></progress><small>Отметки прохождения ставишь самостоятельно.</small></div></div><div class="py-course-grid"><aside class="py-outline"><h4>Маршрут C++</h4><nav aria-label="Уроки C++">${c.stages.map((s,i)=>`<details ${l.stage===i+1?'open':''}><summary>${i+1}. ${s}</summary>${c.lessons.filter(x=>x.stage===i+1).map(x=>`<button data-cpp-open="${x.id}" ${x.id===id?'aria-current="step"':''}>${done.has(x.id)?'✓ ':''}${x.title}</button>`).join('')}</details>`).join('')}</nav><a class="py-reading-link" href="/cpp/">Справочник курса →</a></aside><div class="py-reader"><section class="py-theory"><div class="py-lesson-heading"><span class="eyebrow">${c.stages[l.stage-1]} / ${index+1} ИЗ 22</span><h3 id="cppTitle">${l.title}</h3></div>${l.theory.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="py-example"><h4>Пример программы</h4><pre><code>${esc(l.example)}</code></pre><h4>Ожидаемый вывод</h4><pre>${esc(l.output)}</pre></div><p><b>Частая ошибка.</b> ${esc(l.mistake)}</p><details><summary>Как скомпилировать и запустить</summary><p>Установи компилятор с поддержкой C++17: GCC, Clang или MSVC. Сохрани файл как main.cpp. Для GCC/Clang:</p><pre>g++ -std=c++17 -Wall -Wextra -Wpedantic main.cpp -o main</pre><p>Linux/macOS: <code>./main</code>. Windows в PowerShell: <code>.\\main.exe</code>. Вводи тестовые данные в терминале. Для MSVC используй Developer Command Prompt: <code>cl /std:c++17 /EHsc main.cpp</code>.</p></details></section><section class="py-workspace"><h4>Практика</h4><p>${esc(l.task)}</p><div class="cpp-tests"><h4>Проверь на этих примерах</h4>${l.cases.map(t=>`<details><summary>Ввод и ожидаемый результат</summary><label>Ввод</label><pre>${esc(t.input||'(пустой ввод)')}</pre><label>Вывод</label><pre>${esc(t.output||'(пустой вывод)')}</pre></details>`).join('')}</div><label for="cppCode">Твоё решение</label><textarea id="cppCode" class="py-code-editor" spellcheck="false" aria-describedby="cppEditorHelp">${esc(drafts[id]??l.starter)}</textarea><p id="cppEditorHelp" class="py-editor-help">Редактор сохраняет код. Для компиляции скачай .cpp и запусти его на компьютере. Онлайн-компилятора в этом курсе пока нет.</p><div class="py-run-bar"><button id="cppDownload">↓ Скачать .cpp</button><button id="cppReset">Вернуть шаблон</button><span id="cppSaved">Черновик в этом браузере</span></div><details class="py-solution"><summary>Разбор и эталонное решение</summary><p>Сверь реализацию с контрактом из условия. Прогони все примеры, затем придумай ещё один граничный случай. Объясни, почему твой алгоритм работает и сколько памяти использует.</p><pre><code>${esc(l.solution)}</code></pre></details><section class="cpp-quiz"><h4>Вопрос на понимание</h4><p>${esc(l.quiz.question)}</p>${l.quiz.options.map((o,i)=>`<button class="lab-btn" data-cpp-quiz="${i}">${esc(o)}</button>`).join('')}<p id="cppQuizResult" role="status"></p></section><button id="cppDone" class="lab-btn">${done.has(id)?'Снять отметку прохождения':'Я изучил тему и проверил решение'}</button></section><div class="py-lesson-navigation"><button data-cpp-open="${c.lessons[index-1]?.id||''}" ${index===0?'disabled':''}>← Назад</button><button data-cpp-open="${c.lessons[index+1]?.id||''}" ${index===21?'disabled':''}>Следующая тема →</button></div></div></div>`;}
host.addEventListener('input',e=>{if(e.target.id==='cppCode'){drafts[id]=e.target.value;persist()}});host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const l=c.lessons.find(l=>l.id===id);if(ids.has(b.dataset.cppOpen)){id=b.dataset.cppOpen;render();persist();$('#cppTitle').scrollIntoView({block:'start'});return}if(b.dataset.cppQuiz!==undefined){const ok=Number(b.dataset.cppQuiz)===l.quiz.correct;$('#cppQuizResult').textContent=(ok?'Верно. ':'Попробуй ещё раз. ')+l.quiz.reason;return}if(b.id==='cppDone'){done.has(id)?done.delete(id):done.add(id);render();persist()}if(b.id==='cppReset'){drafts[id]=l.starter;$('#cppCode').value=l.starter;persist()}if(b.id==='cppDownload'){const url=URL.createObjectURL(new Blob([$('#cppCode').value],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='main.cpp';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});render();window.matclubCpp={open(x){if(!ids.has(x))return;id=x;document.getElementById('computingNav').click();document.getElementById('cppTab').click();render()},get state(){return{id,done:[...done]}}};const link=new URLSearchParams(location.search).get('cpp');if(ids.has(link))window.matclubCpp.open(link);
})();
